package com.termux.app.workspace;
import android.app.*;import android.view.*;import android.widget.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import java.util.concurrent.TimeUnit;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,application=Application.class) @LooperMode(LooperMode.Mode.PAUSED)
public class AgentManualScrollTest {
 @Test public void touchDragShowsIndicatorWithoutChangingGestureHandling(){Activity a=Robolectric.buildActivity(Activity.class).setup().visible().get();AgentManualScroll s=new AgentManualScroll(a);View content=new View(a);content.setMinimumHeight(3000);s.addView(content,new ScrollView.LayoutParams(300,3000));a.setContentView(s);s.measure(View.MeasureSpec.makeMeasureSpec(300,1073741824),View.MeasureSpec.makeMeasureSpec(500,1073741824));s.layout(0,0,300,500);long t=android.os.SystemClock.uptimeMillis();MotionEvent down=MotionEvent.obtain(t,t,MotionEvent.ACTION_DOWN,100,350,0),move=MotionEvent.obtain(t,t+40,MotionEvent.ACTION_MOVE,100,200,0),move2=MotionEvent.obtain(t,t+50,MotionEvent.ACTION_MOVE,100,100,0),up=MotionEvent.obtain(t,t+60,MotionEvent.ACTION_UP,100,80,0);try{s.dispatchTouchEvent(down);s.dispatchTouchEvent(move);s.dispatchTouchEvent(move2);assertTrue("Native scroll position must move (Robolectric 4.4 getScrollY uses a separate shadow cache)",(Integer)org.robolectric.util.ReflectionHelpers.getField(s,"mScrollY")>0);assertEquals(1,s.indicatorOpacity(),.001);s.dispatchTouchEvent(up);assertEquals(1,s.indicatorOpacity(),.001);}finally{down.recycle();move.recycle();move2.recycle();up.recycle();s.hideIndicator();a.finish();}}
 @Test public void programmaticScrollingAndLayoutDoNotShowOrExtendIndicator(){Activity a=Robolectric.buildActivity(Activity.class).setup().get();AgentManualScroll s=new AgentManualScroll(a);View content=new View(a);content.setMinimumHeight(3000);s.addView(content,new ScrollView.LayoutParams(300,3000));a.setContentView(s);s.measure(View.MeasureSpec.makeMeasureSpec(300,1073741824),View.MeasureSpec.makeMeasureSpec(500,1073741824));s.layout(0,0,300,500);s.scrollTo(0,100);assertEquals(0,s.indicatorOpacity(),.001);s.manualMovement();assertEquals(1,s.indicatorOpacity(),.001);Shadows.shadowOf(android.os.Looper.getMainLooper()).idleFor(250,TimeUnit.MILLISECONDS);s.scrollTo(0,200);s.requestLayout();Shadows.shadowOf(android.os.Looper.getMainLooper()).idleFor(350,TimeUnit.MILLISECONDS);assertEquals(0,s.indicatorOpacity(),.001);s.fling(1000);s.computeScroll();assertEquals(0,s.indicatorOpacity(),.001);s.hideIndicator();a.finish();}
}
